export type Category =
  | "oxygen-portable"
  | "oxygen-stationary"
  | "oxygen-tank"
  | "oxygen-accessory"
  | "sleep-cpap"
  | "sleep-bipap"
  | "sleep-travel"
  | "sleep-mask"
  | "sleep-cleaner"
  | "respiratory-accessory"
  | "ventilator"
  | "oxygen-rental"
  | "cpap-rental";

export type Badge = "Rental" | "Refurbished" | "Sale" | "Discontinued";

export type Product = {
  slug: string;
  name: string;
  brand: string;
  category: Category;
  price: number | null; // null = call for pricing
  compareAt?: number;
  spec?: string; // real, disclosed spec string only — never fabricated
  faaApproved?: boolean;
  badge?: Badge;
  rxRequired: boolean;
  image?: string; // real product photo path under /public/products — never a stock/placeholder substitute
  specs?: [string, string][]; // real, disclosed full spec table — never fabricated
};

