/** Highest price first (nulls/"Call for Pricing" last) — an honest proxy for
 *  "highest-value item first" since real margin data isn't available. */
function byValueDesc(a: Product, b: Product) {
  if (a.price === null && b.price === null) return 0;
  if (a.price === null) return 1;
  if (b.price === null) return -1;
  return b.price - a.price;
}

export const productsByCategory = (category: Category) =>
  PRODUCTS.filter((p) => p.category === category).sort(byValueDesc);

export function getProduct(category: Category, slug: string) {
  return PRODUCTS.find((p) => p.category === category && p.slug === slug);
}

/** Looks up a product by its URL base segment + slug, spanning categories that share a base (e.g. sleep-cpap + sleep-travel both live under /sleep/cpap). */
export function getProductByBase(base: string, slug: string) {
  return PRODUCTS.find((p) => CATEGORY_META[p.category].base === base && p.slug === slug);
}

export function productsByBase(base: string) {
  return PRODUCTS.filter((p) => CATEGORY_META[p.category].base === base).sort(byValueDesc);
}

/** Real accessories to cross-sell on a machine's PDP — sourced entirely from
 * each accessory's own disclosed "Compatibility" spec field, never a
 * fabricated or inferred pairing. Most accessories in the catalog don't
 * carry a Compatibility field at all, so this only surfaces something for
 * the specific models that actually have one on file. */
export function compatibleAccessories(product: Product): Product[] {
  return PRODUCTS.filter((p) => {
    if (!p.specs) return false;
    const compat = p.specs.find(([label]) => label === "Compatibility")?.[1];
    if (!compat) return false;
    return compat
      .split(",")
      .map((model) => model.trim().toLowerCase())
      .some((model) => product.name.toLowerCase().includes(model) || model === "most cpap/bipap");
  }).filter((p) => {
    // "Most CPAP/BiPAP" accessories only make sense cross-sold on sleep
    // machines, not oxygen equipment — the field says "most", not "all",
    // so this is deliberately scoped to the category it's actually about.
    const compat = p.specs!.find(([label]) => label === "Compatibility")![1];
    if (compat.toLowerCase() === "most cpap/bipap") {
      return product.category === "sleep-cpap" || product.category === "sleep-bipap";
    }
    return true;
  });
}

export function productHref(p: Pick<Product, "category" | "slug">) {
  return href(p);
}

/** Top-level section a product's breadcrumb belongs to, derived from its base path's first segment. */
export function productSection(p: Pick<Product, "category">): { name: string; url: string } {
  const base = CATEGORY_META[p.category].base;
  const firstSegment = "/" + base.split("/")[1];
  const names: Record<string, string> = {
    "/oxygen": "Oxygen",
    "/sleep": "Sleep",
    "/respiratory-accessories": "Respiratory Accessories",
    "/ventilators": "Ventilators",
    "/rentals": "Rentals",
  };
  return { name: names[firstSegment] ?? firstSegment.slice(1), url: firstSegment };
}

// Descriptive alt text for image search — real category label, not a fabricated description.
export function productAltText(p: Pick<Product, "name" | "category">) {
  return `${p.name} — ${CATEGORY_META[p.category].label}`;
}

export function formatPrice(n: number) {
  return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 }).format(n);
}

/** Parses a real disclosed weight spec ("4.8 lbs (standard battery)") into
 * pounds, or a real disclosed battery-life spec ("6-13 hours") into its
 * upper-bound hours. Returns null on anything that doesn't cleanly match —
 * never estimates or falls back to a guessed number. */
function parseLeadingNumber(value: string): number | null {
  const match = value.match(/(\d+(?:\.\d+)?)/);
  return match ? Number(match[1]) : null;
}

function parseUpperBoundNumber(value: string): number | null {
  const matches = value.match(/\d+(?:\.\d+)?/g);
  if (!matches || matches.length === 0) return null;
  return Number(matches[matches.length - 1]);
}

export type WeightPerBatteryHour = { weightLbs: number; maxHours: number; lbsPerHour: number };

/** Weight-per-hour-of-runtime, computed only from this product's own
 * disclosed "Weight" and "Battery Life" spec rows. Returns null if either
 * spec is missing or doesn't parse cleanly — a comparison this site can't
 * verify from real numbers doesn't get published, not even a rounded one. */
export function weightPerBatteryHour(p: Pick<Product, "specs">): WeightPerBatteryHour | null {
  const weightSpec = p.specs?.find(([label]) => label === "Weight")?.[1];
  const batterySpec = p.specs?.find(([label]) => label === "Battery Life")?.[1];
  if (!weightSpec || !batterySpec) return null;
  const weightLbs = parseLeadingNumber(weightSpec);
  const maxHours = parseUpperBoundNumber(batterySpec);
  if (weightLbs === null || maxHours === null || maxHours === 0) return null;
  return { weightLbs, maxHours, lbsPerHour: Math.round((weightLbs / maxHours) * 100) / 100 };
}

