export type RentVsBuyRow = {
  deviceName: string;
  purchaseSlug: string;
  rentalSlug: string;
  purchasePrice: number;
  monthlyRental: number;
  breakevenMonths: number;
};

/** Rent-vs-buy crossover rows, computed live from catalog prices so the
 * table can never drift from what the PDPs actually charge. Only pairs
 * where both prices are real numbers qualify — call-for-pricing SKUs on
 * either side are excluded rather than estimated. */
export function rentVsBuyRows(): RentVsBuyRow[] {
  const rows: RentVsBuyRow[] = [];
  for (const [rentalSlug, purchaseSlug] of Object.entries(RENTAL_PURCHASE_EQUIVALENT)) {
    if (!rentalSlug.endsWith("-monthly-rental")) continue;
    const rental = PRODUCTS.find((p) => p.slug === rentalSlug);
    const purchase = PRODUCTS.find((p) => p.slug === purchaseSlug);
    if (!rental || !purchase || rental.price === null || purchase.price === null) continue;
    rows.push({
      deviceName: purchase.name,
      purchaseSlug,
      rentalSlug,
      purchasePrice: purchase.price,
      monthlyRental: rental.price,
      breakevenMonths: Math.round((purchase.price / rental.price) * 10) / 10,
    });
  }
  return rows.sort((a, b) => a.breakevenMonths - b.breakevenMonths);
}
